const store=()=>{try{return JSON.parse(localStorage.getItem(STORE))||{}}catch{return {}}},save=v=>localStorage.setItem(STORE,JSON.stringify(v));
const profile=()=>{try{return JSON.parse(localStorage.getItem(PROFILE))||{}}catch{return {}}};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
let selected='all',query='',view='recommended',dataCache={};
const profName=slug=>PROFESSIONS.find(p=>p[0]===slug)?.[1]||slug;
function charKey(){const p=profile();return String(p.data?.pseudo||'aventurier').toLowerCase()+'-'+String(p.race||'')+'-'+String(p.classe||'')}
function progress(){const p=profile(),bridge=store().imports?.[charKey()];let imported={};try{imported=JSON.parse(localStorage.getItem('grimoire.bridge.last'))||{}}catch{}const name=String(p.data?.pseudo||'').toLowerCase();return {level:+p.data?.level||1,jobs:p.jobs||[],skills:bridge?.skills||{},known:bridge?.known||[],verified:bridge?.updated||null,faction:['Humain','Nain','Gnome','Elfe'].includes(p.race)?'alliance':'horde',zone:String(imported.name||'').toLowerCase()===name?String(imported.zone||''):''}}
function owned(slug,p){if(!p.jobs?.length)return true;const n=PROFESSIONS.find(x=>x[0]===slug)?.[2];return p.jobs.includes(n)||['Cuisine','Pêche','Premiers secours'].includes(n)||Object.keys(p.skills).some(x=>x.toLowerCase()===n?.toLowerCase())}
function skillOf(slug,p){const n=PROFESSIONS.find(x=>x[0]===slug)?.[2];return Number(p.skills[n]||p.skills[slug]||0)}

function recipeId(r){return r.slug+':'+r.name}
function planned(){return store().planned?.[charKey()]||{}}
function adjustPlan(id,delta){
  const x=store();x.planned=x.planned||{};const byChar=x.planned[charKey()]=x.planned[charKey()]||{};
  const val=Math.max(0,Math.min(99,(Number(byChar[id])||0)+delta));
  if(val)byChar[id]=val;else delete byChar[id];save(x);render();
}
function knownRecipes(){const found=new Map();for(const r of SPECIAL_RECIPES){const id=recipeId(r);if(!found.has(id))found.set(id,r)}return [...found.values()]}
function ingredientRows(recipe,multiplier){
  const raw=String(recipe.reagents||'').trim();
  if(!raw||/consulter|fiche source|autres matériaux|inconnus/i.test(raw))return null;
  const parts=raw.split(/[,;]+/).map(x=>x.trim()).filter(Boolean),items=[];
  for(const part of parts){
    const match=part.match(/^(?:(\d+)\s*[×x]\s*)?(.+)$/i);
    if(!match||!/^[0-9]+\s*[×x]\s*/.test(part))return null;
    items.push({name:match[2].trim(),count:Number(match[1])*multiplier});
  }
  return items.length?items:null;
}
function shoppingSummary(){
 const chosen=planned(),all=knownRecipes(),selected=all.filter(r=>chosen[recipeId(r)]>0);
 const grouped=new Map(),unknown=[];
 for(const r of selected){
   const rows=ingredientRows(r,chosen[recipeId(r)]);
   if(!rows){unknown.push(r);continue}
   for(const x of rows){const k=x.name.toLocaleLowerCase('fr');const v=grouped.get(k)||{name:x.name,count:0};v.count+=x.count;grouped.set(k,v)}
 }
 return {selected,grouped:[...grouped.values()].sort((a,b)=>a.name.localeCompare(b.name,'fr')),unknown};
}
function shoppingText(){
 const s=shoppingSummary();
 return ['LA BINCH — PRÉPARATION ARTISANAT','Personnage : '+(profile().data?.pseudo||'Aventurier'),'',
 'FABRICATIONS',...s.selected.map(r=>(planned()[recipeId(r)]||0)+' × '+r.name+' ('+profName(r.slug)+')'),'',
 'COMPOSANTS CONFIRMÉS',...(s.grouped.length?s.grouped.map(x=>x.count+' × '+x.name):['Aucun décompte fiable disponible']),
 ...(s.unknown.length?['','À VÉRIFIER SUR LES FICHES SOURCE',...s.unknown.map(r=>r.name+' — '+r.url)]:[]),
 '','Les estimations reposent sur les ingrédients documentés : contrôler dans le jeu.'].join('\n');
}
function renderPlanner(){
 const root=$('craft-planner');if(!root)return;const s=shoppingSummary();
 root.innerHTML='<div class="eyebrow">Atelier de guilde · préparation</div><h3>Mon panier de fabrication <span class="craft-counter">'+s.selected.length+'</span></h3>'+
 '<p class="muted">Ajoute une recette depuis ses fiches, choisis une quantité, puis copie les composants pour préparer tes sorties de récolte.</p>'+
 (s.selected.length?'<div class="craft-plan-list">'+s.selected.map(r=>'<div class="craft-plan-row"><span><b>'+esc(r.name)+'</b><small>'+esc(profName(r.slug))+'</small></span><div class="craft-stepper"><button data-plan-minus="'+esc(encodeURIComponent(recipeId(r)))+'" aria-label="Retirer une fabrication">−</button><strong>'+(planned()[recipeId(r)]||0)+'</strong><button data-plan-plus="'+esc(encodeURIComponent(recipeId(r)))+'" aria-label="Ajouter une fabrication">+</button></div></div>').join('')+'</div>':'<p class="muted">Aucune recette sélectionnée pour ce personnage.</p>')+
 (s.grouped.length?'<h4>Composants à réunir</h4><div class="craft-materials">'+s.grouped.map(x=>'<span>'+x.count+' × '+esc(x.name)+'</span>').join('')+'</div>':'')+
 (s.unknown.length?'<p class="muted">Ingrédients incomplets pour '+s.unknown.length+' recette(s) : consulter leur fiche source. Aucun total inventé.</p>':'')+
 '<button type="button" id="craft-copy-plan" '+(!s.selected.length?'disabled':'')+'>Copier la liste de préparation</button>';
 const copy=$('craft-copy-plan');if(copy)copy.onclick=async()=>{const txt=shoppingText();try{await navigator.clipboard.writeText(txt);copy.textContent='Liste copiée'}catch{window.prompt('Copier la liste :',txt)}};
}

function completed(id){return !!store().done?.[charKey()]?.[id]}
function milestoneID(m){return m.slug+':'+m.skill+':'+m.kind+':'+m.title}
function card(m,compact=false){const p=progress(),id=milestoneID(m),done=completed(id),skill=skillOf(m.slug,p),ready=skill>=m.skill&&p.level>=m.level;return '<article class="craft-card '+(done?'craft-done':ready?'craft-ready':'')+'"><div class="craft-meta">'+esc(profName(m.slug))+' · '+esc(m.kind)+' · métier '+m.skill+' · personnage '+m.level+'</div><strong>'+esc(m.title)+'</strong><p>'+esc(m.note)+'</p><div class="craft-actions"><a target="_blank" rel="noopener noreferrer" href="'+esc(m.link)+'">Source</a><button data-craft-mark="'+esc(id)+'">'+(done?'Marquer à faire':'Marquer effectué')+'</button></div></article>'}
function recipeSkill(r){const v=r.skill;return Number(typeof v==='number'?v:(v?.orange??v?.yellow??r.requiredSkill??r.skillRequired??0))||0}
function discoveredAlerts(p){const list=[];for(const [slug,entry] of Object.entries(dataCache)){if(!owned(slug,p))continue;const skill=skillOf(slug,p);for(const r of (entry.list||[])){const src=r.learnedFrom?.sources||r.sources||[];const where=Array.isArray(src)?src:[];const unusual=where.some(x=>!/trainer|formateur/i.test(String(x.type||x.sourceType||'')))||r.isNew||r.changed;const min=recipeSkill(r);if(unusual&&min<=skill+12&&min>=Math.max(1,skill-20)&&r.name){list.push({slug,skill:min,level:1,kind:'Recette à vérifier',title:r.name,note:'Recette '+(r.isNew?'nouvelle dans Forever. ':r.changed?'modifiée dans Forever. ':'')+'Sources : '+(where.slice(0,2).map(x=>[x.type,x.name,x.zone].filter(Boolean).join(' · ')).join(' ; ')||'consulter la fiche détaillée')+'. L’import ne confirme pas si elle est déjà apprise.',link:'https://foreverdb.net/professions/'+slug,priority:r.isNew?96:90})}}
}return list}
function offlineRecipes(p){return SPECIAL_RECIPES.filter(r=>r.priority>=80&&owned(r.slug,p)&&(skillOf(r.slug,p)>0?skillOf(r.slug,p)>=r.skill-12&&skillOf(r.slug,p)<=r.skill+30:p.level>=Math.max(1,Math.floor(r.skill/5))-3&&p.level<=Math.max(1,Math.floor(r.skill/5))+8)&&!completed(milestoneID({slug:r.slug,skill:r.skill,kind:'Patron à récupérer',title:r.name}))).map(r=>({slug:r.slug,skill:r.skill,level:1,kind:'Patron à récupérer',title:r.name,note:'Ingrédients : '+r.reagents+'. Acquisition : '+r.source+'.',link:r.url,priority:r.priority}))}
function alerts(p){const current=MILESTONES.filter(m=>owned(m.slug,p)&&!completed(milestoneID(m))&&m.level<=p.level&&m.level>=p.level-12&&(skillOf(m.slug,p)>0?skillOf(m.slug,p)>=Math.max(0,m.skill-25):m.level>=p.level-8)).sort((a,b)=>b.priority-a.priority||a.skill-b.skill);return current.concat(offlineRecipes(p)).concat(discoveredAlerts(p).filter(x=>!completed(milestoneID(x)))).sort((a,b)=>b.priority-a.priority).slice(0,30)}
function mount(){const app=$('app'),nav=app?.querySelector('nav.nav'),main=app?.querySelector('main');if(!app||!nav||!main||$('page-crafting'))return;
const btn=document.createElement('button');btn.dataset.page='crafting';btn.textContent='Atlas des recettes';nav.insertBefore(btn,nav.querySelector('[data-page="gm"]'));
btn.onclick=()=>{nav.querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===btn));main.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id==='page-crafting'));render();scrollTo({top:0,behavior:'smooth'})};
const page=document.createElement('section');page.id='page-crafting';page.className='page';page.innerHTML='<section class="panel section"><div class="eyebrow">Artisanat · Toutes les professions</div><h2>Atlas des recettes et plans</h2><p class="muted">Alertes de parcours intégrées et catalogue complémentaire ForeverDB avec clé API personnelle facultative. Les sources sans validation en jeu sont signalées comme indicatives.</p><div class="craft-controls"><select id="craft-prof" aria-label="Choisir un métier"><option value="all">Tous les métiers</option></select><input id="craft-search" type="search" placeholder="Rechercher une recette, un plan ou une récompense"><select id="craft-view" aria-label="Vue"><option value="recommended">Parcours et incontournables</option><option value="recipes">Catalogue libre des recettes</option><option value="special">Recettes sourcées & nouveautés</option></select></div><div id="craft-planner" class="panel section craft-planner"></div><div id="craft-body"></div></section>';
main.insertBefore(page,$('page-gm'));for(const p of PROFESSIONS){const o=document.createElement('option');o.value=p[0];o.textContent=p[1];$('craft-prof').append(o)}
$('craft-prof').onchange=e=>{selected=e.target.value;render()};$('craft-search').oninput=e=>{query=e.target.value.toLocaleLowerCase('fr');render()};$('craft-view').onchange=e=>{view=e.target.value;render()};
const hub=$('page-hub');const section=document.createElement('section');section.id='craft-alerts';section.className='panel section';hub.insertBefore(section,hub.querySelector('#hub-cards')||hub.firstChild.nextSibling);
document.addEventListener('click',e=>{const action=e.target.closest('[data-plan-plus],[data-plan-minus]');if(action){let id;try{id=decodeURIComponent(action.dataset.planPlus||action.dataset.planMinus)}catch{return}adjustPlan(id,action.hasAttribute('data-plan-plus')?1:-1);return}const el=e.target.closest('[data-craft-mark]');if(!el)return;const state=store();state.done=state.done||{};state.done[charKey()]=state.done[charKey()]||{};state.done[charKey()][el.dataset.craftMark]=!state.done[charKey()][el.dataset.craftMark];save(state);render()});
$('level')?.addEventListener('input',()=>setTimeout(render,0));document.addEventListener('grimoire:sync',render);window.addEventListener('storage',render);
render();
}
function relevantStations(p){const z=p.zone.toLowerCase();if(!z)return [];const aliases={'hurlevent':'stormwind city','forgefer':'ironforge','fossoyeuse':'undercity','tarides':'barrens','marche de l’ouest':'westfall','clairières de tirisfal':'tirisfal glades','montagnes d’alterac':'alterac mountains','vallée de strangleronce':'stranglethorn vale','marécage des chagrins':'swamp of sorrows','forêt d’elwynn':'elwynn forest','loch modan':'loch modan'};return CRAFT_STATIONS.filter(x=>(x.zone.toLowerCase()===z||aliases[z]===x.zone.toLowerCase()||aliases[x.zone.toLowerCase()]===z)&&(x.faction==='both'||x.faction===p.faction)&&owned(x.slug,p)&&skillOf(x.slug,p)>=Math.max(0,x.skill-50)).slice(0,3)}
function render(){if(!$('craft-body'))return;renderPlanner();const p=progress(),a=alerts(p),now=a.slice(0,3),stations=relevantStations(p);$('craft-alerts').innerHTML='<div class="eyebrow">Carnet de route · Artisanat</div><h2>Recettes à ne pas manquer'+(a.length?' <span class="craft-counter">'+a.length+'</span>':'')+'</h2><p class="muted">'+(p.verified?'Compétences importées depuis WoW (dernier import : '+esc(new Date(p.verified).toLocaleDateString('fr-FR'))+').':'Compétences de métier non synchronisées : alertes indicatives fondées sur le niveau et les métiers sélectionnés.')+'</p><div class="craft-stack">'+(now.length?now.map(x=>card(x,true)).join(''):'<p>Aucune étape d’artisanat prioritaire actuellement.</p>')+'</div>'+(stations.length?'<div class="craft-nearby"><strong>Sur ton parcours · '+esc(p.zone)+'</strong>'+stations.map(x=>'<p>📍 '+esc(x.npc)+' · '+esc(profName(x.slug))+' · /way '+esc(x.coords)+' · <a target="_blank" rel="noopener noreferrer" href="'+esc(x.source)+'">guide</a></p>').join('')+'</div>':'')+'<button id="craft-open" class="craft-open">Voir l’atlas complet</button>';
$('craft-open').onclick=()=>$('app').querySelector('[data-page="crafting"]').click();
if(view==='recipes'){renderRecipes();return}if(view==='special'){renderSpecial();return}
const filtered=MILESTONES.filter(x=>(selected==='all'||x.slug===selected)&&(!query||[x.title,x.note,profName(x.slug)].join(' ').toLocaleLowerCase('fr').includes(query))).sort((a,b)=>a.skill-b.skill||b.priority-a.priority);
$('craft-body').innerHTML='<p class="muted">'+filtered.length+' étapes documentées · progression selon compétence métier et niveau de personnage. Les alertes ne prouvent pas que le personnage connaît ou ignore un patron.</p><div class="craft-stack">'+filtered.map(m=>card(m)).join('')+'</div>';
}
function renderSpecial(){const list=knownRecipes().filter(x=>(selected==='all'||x.slug===selected)&&(!query||[x.name,x.reagents,x.source,x.kind].join(' ').toLocaleLowerCase('fr').includes(query))).sort((a,b)=>a.skill-b.skill);$('craft-body').innerHTML='<p>'+list.length+' recettes issues de guides Forever. Certains ingrédients ou lieux restent à confirmer. Tous les autres patrons sont accessibles dans les catalogues complets sans clé.</p><div class="craft-stack">'+list.map(r=>'<article class="craft-card"><div class="craft-meta">'+esc(profName(r.slug))+' · compétence '+r.skill+'</div><strong>'+esc(r.name)+'</strong><p><b>Matériaux :</b> '+esc(r.reagents)+'</p><p><b>Source :</b> '+esc(r.source)+'</p><div class="craft-actions"><a href="'+esc(r.url)+'" target="_blank" rel="noopener noreferrer">Fiche source</a></div></article>').join('')+'</div>'}
function normList(x){if(Array.isArray(x))return x;for(const prop of ['recipes','data','results','items']){if(Array.isArray(x?.[prop]))return x[prop];if(Array.isArray(x?.data?.[prop]))return x.data[prop]}return []}
function recipeItem(x){const name=x.name||x.recipeName||x.spellName||'Recette sans nom',sk=x.skill||{},rank=typeof sk==='number'?sk:(sk.yellow??sk.orange??x.requiredSkill??x.skillRequired??'?');const sources=x.learnedFrom?.sources||x.sources||[];const how=Array.isArray(sources)?sources.slice(0,3).map(y=>[y.type,y.name,y.zone].filter(Boolean).join(' · ')).join(' ; '):'';const mats=x.reagents||x.materials||[];const ingredients=Array.isArray(mats)?mats.slice(0,12).map(r=>(r.count||r.quantity||1)+' × '+(r.name||r.item?.name||r.itemName||'Composant')).join(', '):'';return '<article class="craft-card"><div class="craft-meta">'+esc(x.isNew?'Nouveauté Forever':x.changed?'Recette modifiée':'Recette')+' · compétence '+esc(rank)+'</div><strong>'+esc(name)+'</strong><p>'+esc(ingredients||'Ingrédients non communiqués')+'</p><p class="craft-meta">Apprentissage : '+esc(how||x.learnedFrom?.type||'Voir les sources dans ForeverDB')+'</p></article>'}
function renderRecipes(){const root=$('craft-body');const prof=selected==='all'?PROFESSIONS[0][0]:selected;if(selected==='all'){$('craft-prof').value=prof;selected=prof}
const cached=dataCache[prof],cfg=store();root.innerHTML='<p><strong>Catalogue complet gratuit :</strong> <a target="_blank" rel="noopener noreferrer" href="'+esc(PUBLIC_CATALOGS[prof])+'">Everloot — '+esc(profName(prof))+'</a> · <a target="_blank" rel="noopener noreferrer" href="https://everloot.app/tools/professions/'+encodeURIComponent(prof)+'">Everloot</a> · <a target="_blank" rel="noopener noreferrer" href="https://foreverdb.net/professions/'+encodeURIComponent(prof)+'">ForeverDB</a>. Ces liens fonctionnent sans clé. L’import API détaillé ci-dessous est facultatif.</p><div class="craft-controls"><input type="password" id="craft-api-key" autocomplete="off" placeholder="Clé API ForeverDB (facultative)"><button id="craft-load">Charger les recettes</button><button id="craft-next" '+(!cached?.next?'disabled':'')+'>Page suivante</button></div><p id="craft-data-status" class="muted">'+(cached?cached.list.length+' recettes récupérées dans cette session.':'Aucune donnée API chargée : les parcours locaux restent disponibles hors ligne.')+'</p><div id="craft-recipes" class="craft-stack">'+(cached?.list||[]).filter(x=>!query||String(x.name||x.recipeName||'').toLocaleLowerCase('fr').includes(query)).map(recipeItem).join('')+'</div>';const key=$('craft-api-key');$('craft-load').onclick=()=>loadRecipes(prof,key.value,false);$('craft-next').onclick=()=>loadRecipes(prof,key.value,true)}
async function loadRecipes(prof,key,next){const status=$('craft-data-status');if(!key){status.textContent='Clé personnelle nécessaire pour accéder à l’API. Le parcours reste disponible sans compte.';return}const offset=next?(dataCache[prof]?.list.length||0):0;status.textContent='Chargement sécurisé depuis ForeverDB…';try{
const url='https://foreverdb.net/api/v1/professions/'+encodeURIComponent(prof)+'?limit=100&offset='+offset;
const res=await fetch(url,{headers:{'X-API-Key':key},cache:'no-store'});if(!res.ok)throw Error('HTTP '+res.status);
const data=await res.json(),list=normList(data),current=next?(dataCache[prof]?.list||[]):[];
dataCache[prof]={list:current.concat(list),next:list.length>=100};render();
}catch(e){status.textContent='Impossible de charger le catalogue ('+e.message+'). Les étapes locales restent disponibles.'}}
const css=document.createElement('style');css.textContent='.craft-controls{display:flex;gap:9px;flex-wrap:wrap;margin:15px 0}.craft-controls input,.craft-controls select,.craft-controls button,.craft-open{padding:10px;border:1px solid var(--line);background:#17241c;color:var(--ink);border-radius:6px;max-width:100%}.craft-controls input{flex:1;min-width:190px}.craft-nearby{padding:12px;margin-top:12px;border:1px solid var(--line);border-radius:8px;background:#121b14}.craft-nearby p{margin:5px 0}.craft-nearby a{color:var(--gold)}.craft-stack{display:grid;gap:12px}.craft-card{background:#09110eeb;border:1px solid var(--line);border-radius:8px;padding:14px;display:grid;gap:7px}.craft-card p{margin:0}.craft-card strong{font-size:1.05rem}.craft-meta{font-size:.8rem;color:var(--muted)}.craft-actions{display:flex;flex-wrap:wrap;gap:12px;align-items:center}.craft-actions a{color:var(--gold)}.craft-actions button{background:#25352b;color:var(--ink);padding:7px 12px;border:1px solid var(--line);border-radius:5px;cursor:pointer}.craft-ready{border-left:4px solid #e9c375}.craft-done{opacity:.6}.craft-counter{font-size:.85rem;background:#594329;padding:3px 8px;border-radius:10px}.craft-open{margin-top:12px;cursor:pointer}';
css.textContent+='.craft-planner{margin:16px 0}.craft-planner h3{margin:4px 0 12px}.craft-plan-list{display:grid;gap:7px;margin:12px 0}.craft-plan-row{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:9px;border:1px solid var(--line);border-radius:7px}.craft-plan-row small{display:block;color:var(--muted)}.craft-stepper{display:flex;align-items:center;gap:12px}.craft-stepper button,#craft-copy-plan{border:1px solid var(--line);background:#28342b;color:var(--ink);padding:8px 12px;border-radius:6px;cursor:pointer}.craft-materials{display:flex;flex-wrap:wrap;gap:8px;margin:10px 0 16px}.craft-materials span{border:1px solid var(--line);border-radius:6px;padding:6px 10px;background:#111c15}';document.head.append(css);
